create table t1(a integer primary key, b text not null, c real default 1.5, d unique);
create index t1b on t1(b);
insert into t1(b, d) values('x', 1), ('y', 2), ('z', 3);
insert into t1 values(10, 'w', 2.5, 4);
insert into t1(b, d) values('dup', 2);
insert or ignore into t1(b, d) values('dup', 2);
insert or replace into t1(b, d) values('rep', 2);
select * from t1 order by a;
update t1 set c = c * 2 where a > 2;
update t1 set b = upper(b);
select * from t1 order by a;
delete from t1 where d = 4;
select count(*), sum(c) from t1;
create table t2(id integer primary key autoincrement, v);
insert into t2(v) values(1),(2),(3);
delete from t2 where id = 3;
insert into t2(v) values(4);
select * from t2;
select * from sqlite_sequence;
create table t3(k text primary key, v int) without rowid;
insert into t3 values('b', 2), ('a', 1), ('c', 3);
insert into t3 values('a', 9) on conflict(k) do update set v = excluded.v + 100;
select * from t3;
create table log(msg);
create trigger tr1 after insert on t3 begin insert into log values('ins ' || new.k); end;
create trigger tr2 before delete on t3 begin insert into log values('del ' || old.k); end;
insert into t3 values('d', 4);
delete from t3 where k = 'b';
select * from log;
create table par(id integer primary key, n);
create table chi(id integer primary key, p references par(id) on delete cascade);
insert into par values(1, 'one'), (2, 'two');
insert into chi values(1, 1), (2, 2), (3, 1);
delete from par where id = 1;
select * from chi;
insert into t1(b, d) values('ret', 9) returning a, b, d;
create table g(a, b as (a * 2) stored, c as (a + 1));
insert into g(a) values(5), (6);
select * from g;
create table ck(x check (x > 0));
insert into ck values(5);
insert into ck values(-1);
select * from ck;
begin;
insert into t2(v) values(100);
savepoint s1;
insert into t2(v) values(200);
rollback to s1;
commit;
select * from t2;
create view vw as select a, b from t1;
select * from vw order by a;
update t1 set c = 0 where a in (select a from t1 where b like 'X%');
select a, c from t1 order by a;
